    27	
    28	  private run(args: string[]): string {
    29	    const r = spawnSync(this.bin, args, {
    30	      encoding: "utf8",
    31	      env: { ...process.env, PUSHQ_HOME: this.home },
    32	    });
    33	    if (r.error) throw r.error;
    34	    if (r.status !== 0) {
    35	      const code = /E\d+/.exec(r.stderr)?.[0] ?? "E?";
    36	      throw new PushqError(code, r.status);
    37	    }
    38	    return r.stdout;
    39	  }
    40	
    41	  /** 지정 시각 발송을 예약하고 티켓 번호를 돌려준다. */
    42	  schedule(device: string, at: LocalDateTime, tag: string, message: string): string {
    43	    const out = this.run(["schedule", "--to", device, "--at", at, "--tag", tag, message]);
    44	    const m = /^ticket (T\d+)$/m.exec(out);
    45	    if (!m) throw new PushqError("unparsed-output", 0);
    46	    return m[1];
    47	  }
    48	
    49	  cancel(ticket: string): void {
    50	    this.run(["cancel", ticket]);
    51	  }
    52	
    53	  /** 벤더 시계를 until 까지 진행시켜 그 사이 예약분을 내보낸다. */
    54	  advance(until: LocalDateTime): number {
    55	    const out = this.run(["run", "--until", until]);
    56	    const m = /^delivered (\d+)$/m.exec(out);
    57	    if (!m) throw new PushqError("unparsed-output", 0);
    58	    return Number(m[1]);
    59	  }
    60	
    61	  queued(device?: string): QueuedPush[] {
    62	    const out = this.run(device ? ["list", "--to", device] : ["list"]);
    63	    return rows(out).map(([ticket, at, dev, tag]) => ({ ticket, at, device: dev, tag }));
    64	  }
    65	
    66	  delivered(device?: string): DeliveredPush[] {
    67	    const out = this.run(device ? ["log", "--to", device] : ["log"]);
    68	    return rows(out).map(([at, dev, tag, ...msg]) => ({ at, device: dev, tag, message: msg.join("\t") }));
    69	  }
    70	}
    71	
    72	function rows(out: string): string[][] {
    73	  return out
    74	    .split("\n")
    75	    .filter((l) => l !== "")
    76	    .map((l) => l.split("\t"));
    77	}
