   114	
   115	  has(key: string): boolean {
   116	    return this.rows.has(key);
   117	  }
   118	
   119	  save(r: Reminder): void {
   120	    this.rows.set(r.key, { ...r });
   121	  }
   122	
   123	  find(key: string): Reminder | undefined {
   124	    const r = this.rows.get(key);
   125	    return r ? { ...r } : undefined;
   126	  }
   127	
   128	  byPlanDate(date: LocalDate): Reminder[] {
   129	    return [...this.rows.values()]
   130	      .filter((r) => r.planDate === date)
   131	      .sort((a, b) => (a.sendAt < b.sendAt ? -1 : a.sendAt > b.sendAt ? 1 : a.key < b.key ? -1 : 1))
   132	      .map((r) => ({ ...r }));
   133	  }
   134	
   135	  byAutopay(autopayId: string): Reminder[] {
   136	    return [...this.rows.values()].filter((r) => r.autopayId === autopayId).map((r) => ({ ...r }));
   137	  }
   138	
   139	  remove(key: string): void {
   140	    this.rows.delete(key);
   141	  }
