 1	import { AppConfig } from "../config";
 2	import { validateAutopay } from "../domain/autopay";
 3	import { validateMember } from "../domain/member";
 4	import { normalizeDevice } from "../push/deviceToken";
 5	import { PushqClient } from "../push/pushqClient";
 6	import { ReminderReportBuilder } from "../report/reminderReport";
 7	import { AutopayRepository } from "../repository/autopayRepository";
 8	import { MemberRepository } from "../repository/memberRepository";
 9	import { ReminderService } from "../service/reminderService";
10	import { isLocalDateTime } from "../time/localTime";
11	import { notFound, ok, Router } from "./router";
12	
13	const DATE = /^\d{4}-\d{2}-\d{2}$/;
14	
15	export function mountAccountRoutes(router: Router, config: AppConfig, members: MemberRepository, autopays: AutopayRepository): void {
16	  router.add("POST", "/members", (_p, body) => {
17	    const m = validateMember(body, config.allowedLeads);
18	    return ok(members.save({ ...m, device: normalizeDevice(m.device) }));
19	  });
20	
21	  router.add("POST", "/autopays", (_p, body) => {
22	    const input = validateAutopay(body);
23	    if (!members.find(input.memberId)) return notFound(`member ${input.memberId}`);
24	    return ok(autopays.create(input));
25	  });
26	}
27	
28	export function mountReminderRoutes(
29	  router: Router,
30	  service: ReminderService,
31	  report: ReminderReportBuilder,
32	  members: MemberRepository,
33	  push: PushqClient,
34	): void {
35	  router.add("POST", "/reminders/plan", (_p, body) => {
36	    const date = (body as { date?: unknown } | undefined)?.date;
37	    if (typeof date !== "string" || !DATE.test(date)) throw new Error("date must be YYYY-MM-DD");
38	    return ok(service.planDay(date));
39	  });
40	
41	  router.add("POST", "/autopays/:id/failures", (p, body) => ok(service.recordFailure(p.id, body)));
42	
43	  router.add("POST", "/autopays/:id/cancel", (p) => ok(service.cancelAutopay(p.id)));
44	
45	  router.add("POST", "/clock", (_p, body) => {
46	    const until = (body as { until?: unknown } | undefined)?.until;
47	    if (!isLocalDateTime(until)) throw new Error("until must be YYYY-MM-DDTHH:MM:SS");
48	    return ok(service.advance(until));
49	  });
50	
51	  router.add("GET", "/reports/reminders/:date", (p) => {
52	    if (!DATE.test(p.date)) throw new Error("date must be YYYY-MM-DD");
53	    return ok(report.build(p.date, service.now()));
54	  });
55	
56	  router.add("GET", "/members/:id/notifications", (p) => {
57	    const m = members.find(p.id);
58	    if (!m) return notFound(`member ${p.id}`);
59	    const notifications = push.delivered(m.device).map((d) => ({ at: d.at, tag: d.tag, message: d.message }));
60	    return ok({ memberId: m.id, notifications });
61	  });
62	}
 1	import { Member } from "../domain/member";
 2	
 3	export class MemberRepository {
 4	  private readonly rows = new Map<string, Member>();
 5	
 6	  save(m: Member): Member {
 7	    this.rows.set(m.id, { ...m });
 8	    return m;
 9	  }
10	
11	  find(id: string): Member | undefined {
12	    const m = this.rows.get(id);
13	    return m ? { ...m } : undefined;
14	  }
15	
16	  all(): Member[] {
17	    return [...this.rows.values()].map((m) => ({ ...m }));
18	  }
19	}
20	export interface Member {
21	  id: string;
22	  name: string;
23	  /** 앱 푸시 기기 토큰 — "ios:" 또는 "and:" 접두 */
24	  device: string;
25	  /** 출금 예정 알림을 출금 몇 분 전에 받을지 */
26	  leadMinutes: number;
27	  pushOptIn: boolean;
28	}
29	
30	export function validateMember(input: unknown, allowedLeads: number[]): Omit<Member, "device"> & { device: string } {
31	  const b = (input ?? {}) as Record<string, unknown>;
32	  if (typeof b.id !== "string" || !/^M\d{4,}$/.test(b.id)) throw new Error("member id must look like M1234");
33	  if (typeof b.name !== "string" || b.name.trim() === "") throw new Error("name required");
34	  if (typeof b.device !== "string") throw new Error("device required");
35	  const lead = b.leadMinutes === undefined ? 30 : b.leadMinutes;
36	  if (typeof lead !== "number" || !allowedLeads.includes(lead)) throw new Error(`leadMinutes must be one of ${allowedLeads.join(",")}`);
37	  return {
38	    id: b.id,
39	    name: b.name.trim(),
40	    device: b.device,
41	    leadMinutes: lead,
42	    pushOptIn: b.pushOptIn !== false,
43	  };
44	}
45	import { Autopay, BillingFailure } from "../domain/autopay";
46	
47	export class AutopayRepository {
48	  private readonly rows = new Map<string, Autopay>();
49	  private readonly failures: BillingFailure[] = [];
50	  private seq = 0;
51	
52	  create(input: Omit<Autopay, "id" | "active">): Autopay {
53	    this.seq++;
54	    const a: Autopay = { ...input, id: `AP${String(this.seq).padStart(5, "0")}`, active: true };
55	    this.rows.set(a.id, a);
56	    return { ...a };
57	  }
58	
59	  find(id: string): Autopay | undefined {
60	    const a = this.rows.get(id);
61	    return a ? { ...a } : undefined;
62	  }
63	
64	  deactivate(id: string): void {
65	    const a = this.rows.get(id);
66	    if (a) a.active = false;
67	  }
68	
69	  /** 해당 출금일에 출금되는 활성 계약 — 등록 순 */
70	  billingOn(day: number): Autopay[] {
71	    return [...this.rows.values()].filter((a) => a.active && a.billingDay === day).map((a) => ({ ...a }));
72	  }
73	
74	  addFailure(f: BillingFailure): void {
75	    this.failures.push({ ...f });
76	  }
77	
78	  failuresOf(autopayId: string): BillingFailure[] {
79	    return this.failures.filter((f) => f.autopayId === autopayId).map((f) => ({ ...f }));
80	  }
81	}

